import sys

fmod = 998244353

def fmul(a, b):
    return (a * b) % fmod

def fpow(a, b):
    result = 1
    base = a
    exp = b
    while exp > 0:
        if exp & 1:
            result = fmul(result, base)
        base = fmul(base, base)
        exp >>= 1
    return result

def ifact(x, ifact_cache, fact):
    if ifact_cache[x] > 0:
        return ifact_cache[x]
    else:
        ifact_cache[x] = fpow(fact[x], fmod - 2)
        return ifact_cache[x]

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    kl = int(input_data[1])
    if kl >= n:
        print(0)
        return
    k = int(kl)
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fmul(fact[i - 1], i)
    ifact_cache = [0] * (n + 1)
    ans = 0
    for i in range(n - k + 1):
        sign = 1 if i % 2 == 0 else -1
        term = fmul(sign, fmul(fpow(n - k - i, n), fmul(fact[n - k], fmul(ifact(i, ifact_cache, fact), ifact(n - k, ifact_cache, fact)))))
        if term < 0:
            term += fmod
        ans += term
        if ans >= fmod:
            ans -= fmod
    res = fmul(fmul(ans, fact[n]), fmul(ifact(k, ifact_cache, fact), ifact(n - k, ifact_cache, fact)))
    if k == 0:
        print(res)
    else:
        print(fmul(res, 2))

if __name__ == "__main__":
    main()

